runs.command:
python3 ~/.omp/agent/scripts/heavy.py "npx vitest run 2>&1 | tail -n 4 && npx astro check 2>&1 | tail -n 4 && npx astro build 2>&1 | tail -n 2 && node prototypes/logos.mjs http://127.0.0.1:27434 after" && ls site/_astro | grep -cE '^[0-9a-f]{40}-.*\.svg$'; node -e "
const sharp=require('sharp');
(async()=>{for (const n of ['alma-hero','case-studies-grid','home-marquee']){
const [a,b]=await Promise.all(['before','after'].map(s=>sharp('prototypes/'+n+'-'+s+'.png').greyscale().raw().toBuffer({resolveWithObject:true})));
let sum=0,big=0;for(let i=0;i<a.data.length;i++){const d=Math.abs(a.data[i]-b.data[i]);sum+=d;if(d>64)big++}
console.log(n,'mean',(sum/a.data.length).toFixed(3),'px>64',big)}
for(const s of ['before','after']) await sharp('prototypes/alma-hero-'+s+'.png').extract({left:560,top:90,width:140,height:100}).resize(560,400,{kernel:'nearest'}).toFile('prototypes/alma-zoom-'+s+'.png');})()"
